export function getMemberColor(member) {
	if (!member) return "";
	const m = String(member)
		.trim()
		.toLowerCase()
		.replace(/^s\d+\s+/, "");
	return MEMBER_COLORS[m] || "";
}

const seasonColorMap = new Map();

export function getSeasonColor(season) {
	if (!season) return "";
	const s = season.toLowerCase();
	if (seasonColorMap.has(s)) return seasonColorMap.get(s);

	let hash = 0;
	for (let i = 0; i < s.length; i++) {
		hash = s.charCodeAt(i) + ((hash << 5) - hash);
	}
	const index = Math.abs(hash) % SEASON_COLORS.length;
	const color = SEASON_COLORS[index];

	seasonColorMap.set(s, color);
	return color;
}

export function escapeHtml(s) {
	return String(s).replace(
		/[&<>"']/g,
		(c) =>
			({
				"&": "&amp;",
				"<": "&lt;",
				">": "&gt;",
				'"': "&quot;",
				"'": "&#39;",
			})[c],
	);
}

